253	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
254	function parseMaxInterval(raw: string): number | null {
255	  const v = raw.trim();
256	  if (!/^\d+$/.test(v)) return null;
257	  const n = Number(v);
258	  if (!Number.isSafeInteger(n) || n < 1) return null;
259	  return n;
260	}
