317	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
318	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
319	  const out = new Map<string, string[]>();
320	  for (let i = 0; i < rest.length; i++) {
321	    let opt = rest[i];
322	    let value: string | undefined;
323	    const eq = opt.indexOf('=');
324	    if (opt.startsWith('--') && eq !== -1) {
325	      value = opt.slice(eq + 1);
326	      opt = opt.slice(0, eq);
327	    } else if (opt.startsWith('--')) {
328	      value = rest[i + 1];
329	      if (value === undefined) return `选项 '${opt}' 缺少值`;
330	      i++;
331	    } else {
332	      return `无法识别的参数 '${opt}'`;
333	    }
334	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
335	    const list = out.get(opt);
336	    if (list) list.push(value);
337	    else out.set(opt, [value]);
338	  }
339	  return out;
340	}
