358	function cmdRule(rest: string[]): number {
359	  const [sub, ...subrest] = rest;
360	  if (sub === 'list') {
361	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
362	    return cmdRuleList();
363	  }
364	  if (sub === 'create') {
365	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz', '--max-interval']);
366	    if (typeof flags === 'string') return usageError(flags);
367	    const idRaw = oneFlag(flags, '--id');
368	    const deviceList = flags.get('--device');
369	    const groupList = flags.get('--group');
370	    const thresholdRaw = oneFlag(flags, '--threshold');
371	    const tzList = flags.get('--tz');
372	    const maxIntervalList = flags.get('--max-interval');
373	    if (idRaw === null || thresholdRaw === null) {
374	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
375	    }
376	    if (tzList !== undefined && tzList.length !== 1) {
377	      return usageError("'rule create' 的 --tz 只能出现一次");
378	    }
379	    if (maxIntervalList !== undefined && maxIntervalList.length !== 1) {
380	      return usageError("'rule create' 的 --max-interval 只能出现一次");
381	    }
382	    const hasDevice = deviceList !== undefined;
383	    const hasGroup = groupList !== undefined;
384	    if (hasDevice === hasGroup) {
385	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
386	    }
387	    if ((deviceList !== undefined && deviceList.length !== 1) ||
388	      (groupList !== undefined && groupList.length !== 1)) {
389	      return usageError("'rule create' 的目标选项只能出现一次");
390	    }
391	    const id = idRaw.trim();
392	    if (id === '') return usageError('规则标识不能为空');
393	    const thresholdMilli = parseKwh(thresholdRaw.trim());
394	    if (thresholdMilli === null) {
395	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
396	    }
397	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
398	    let tz = 'UTC';
399	    if (tzList !== undefined) {
400	      const tzRaw = tzList[0].trim();
401	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
402	      const canonical = canonicalTimezone(tzRaw);
403	      if (canonical === null) {
404	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
405	      }
406	      tz = canonical;
407	    }
408	    // 采样间隔限制省略为无上限,创建后固定。
409	    let maxInterval: number | undefined;
410	    if (maxIntervalList !== undefined) {
411	      const parsed = parseMaxInterval(maxIntervalList[0]);
412	      if (parsed === null) {
413	        return usageError(`选项 '--max-interval' 的值无效: '${maxIntervalList[0].trim()}'(需正整数秒数)`);
414	      }
415	      maxInterval = parsed;
416	    }
417	    if (hasDevice) {
418	      const device = (deviceList as string[])[0].trim();
419	      if (device === '') return usageError("'--device' 的值不能为空");
420	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli, tz, maxInterval });
421	    }
422	    const group = (groupList as string[])[0].trim();
423	    if (group === '') return usageError("'--group' 的值不能为空");
424	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli, tz, maxInterval });
425	  }
426	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
427	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
428	}
