172	/** 在按时刻升序的时序中找最后一条 ts <= s 的下标,无则 -1。 */
173	function floorIndex(series: Reading[], s: number): number {
174	  let lo = 0;
175	  let hi = series.length - 1;
176	  let ans = -1;
177	  while (lo <= hi) {
178	    const mid = (lo + hi) >> 1;
179	    if (series[mid].ts <= s) {
180	      ans = mid;
181	      lo = mid + 1;
182	    } else {
183	      hi = mid - 1;
184	    }
185	  }
186	  return ans;
187	}
