189	type SliceKind = 'valid' | 'anomaly' | 'unknown';
190	
191	interface DeviceSlice {
192	  kind: SliceKind;
193	  consumption: bigint;
194	  /** kind 为 unknown 且由超过采样间隔限制的区间造成时的原始区间(相邻读数时刻)。 */
195	  gap?: { start: number; end: number };
196	}
197	
198	/**
199	 * 单设备在片段 [s, e) 上的状态与消耗。片段完全落在同一读数区间内
200	 * (调用方保证切点包含区间内全部读数时刻)。非下降区间以区间起点累计
201	 * 比例向下取整,消耗为两端累计量之差;下降区间为异常;首条读数之前、
202	 * 末条之后及孤立读数时段为未知,不外推。maxInterval 为可选的最大采样
203	 * 间隔限制(秒):非下降区间的完整实际时间差(不按片段裁短)超过限制时
204	 * 整个区间为未知,等于限制仍可信;下降区间即使超过限制仍为异常。
205	 */
206	function deviceSlice(
207	  series: Reading[],
208	  s: number,
209	  e: number,
210	  maxInterval?: number,
211	): DeviceSlice {
212	  const i = floorIndex(series, s);
213	  if (i < 0 || i + 1 >= series.length) return { kind: 'unknown', consumption: 0n };
214	  const a = series[i];
215	  const b = series[i + 1];
216	  const diff = b.milli - a.milli;
217	  if (diff < 0n) return { kind: 'anomaly', consumption: 0n };
218	  if (maxInterval !== undefined && b.ts - a.ts > maxInterval) {
219	    return { kind: 'unknown', consumption: 0n, gap: { start: a.ts, end: b.ts } };
220	  }
221	  const duration = BigInt(b.ts - a.ts);
222	  const cumulative = (t: number): bigint => (diff * BigInt(t - a.ts)) / duration;
223	  return { kind: 'valid', consumption: cumulative(e) - cumulative(s) };
224	}
225	
226	export interface GroupPeriod {
227	  /** 时段起点(含),epoch 秒。 */
228	  start: number;
229	  /** 时段终点(不含),epoch 秒。 */
230	  end: number;
231	  /** 该时段生效成员;null 表示首个版本生效前(未知)。 */
232	  members: string[] | null;
233	}
234	
235	export interface GroupSegmentStats {
236	  /** 有效(全部成员非下降且未超采样间隔限制)覆盖秒数,按分组实际时间计。 */
237	  valid: number;
238	  /** 异常(任一成员下降)覆盖秒数。 */
239	  anomaly: number;
240	  /** 未知(无生效版本或任一成员未知)覆盖秒数。 */
241	  unknown: number;
242	  /** unknown 中由成员过长区间造成的秒数:只在最终未知时段内按实际时间
243	   *  计并集,不叠加成员秒数。 */
244	  gapUnknown: number;
245	  /** 与统计范围相交的成员过长区间明细(设备与原始相邻读数时刻),已去重。 */
246	  gaps: GapDetail[];
247	  /** 有效时段内全部生效成员的分摊消耗之和,毫千瓦时 BigInt。 */
248	  consumption: bigint;
249	  /** 段内按生效时刻切分的成员时段。 */
250	  periods: GroupPeriod[];
251	}
252	
253	/**
254	 * 计算分组在 [segStart, segEnd) 上的覆盖与消耗。
255	 * versions 按生效时刻升序;seriesByDevice 含全部版本成员的完整时序。
256	 * maxInterval 为可选的最大采样间隔限制(秒),按完整已存时序的相邻读数
257	 * 实际时间差判定,等于限制仍可信。
258	 */
259	export function computeGroupSegment(
260	  versions: GroupVersion[],
261	  seriesByDevice: Map<string, Reading[]>,
262	  segStart: number,
263	  segEnd: number,
264	  maxInterval?: number,
265	): GroupSegmentStats {
266	  // 按版本生效时刻把段切成成员恒定的时段;首个版本生效前 members 为 null。
267	  const periods: GroupPeriod[] = [];
268	  let idx = -1;
269	  for (let i = 0; i < versions.length; i++) {
270	    if (versions[i].at <= segStart) idx = i;
271	    else break;
272	  }
273	  let cursor = segStart;
274	  while (cursor < segEnd) {
275	    const nextAt = idx + 1 < versions.length ? versions[idx + 1].at : Number.POSITIVE_INFINITY;
276	    const pEnd = Math.min(segEnd, nextAt);
277	    periods.push({ start: cursor, end: pEnd, members: idx >= 0 ? versions[idx].members : null });
278	    cursor = pEnd;
279	    idx++;
280	  }
281	
282	  let valid = 0;
283	  let anomaly = 0;
284	  let unknown = 0;
285	  let gapUnknown = 0;
286	  const gaps: GapDetail[] = [];
287	  let consumption = 0n;
288	  for (const p of periods) {
289	    if (p.members === null) {
290	      unknown += p.end - p.start;
291	      continue;
292	    }
293	    // 切点:时段边界与全部成员的读数时刻;相邻切点间每个成员的状态恒定。
294	    const bounds = new Set<number>([p.start, p.end]);
295	    for (const m of p.members) {
296	      for (const r of seriesByDevice.get(m) ?? []) {
297	        if (r.ts > p.start && r.ts < p.end) bounds.add(r.ts);
298	      }
299	    }
300	    const sorted = [...bounds].sort((a, b) => a - b);
301	    for (let k = 0; k + 1 < sorted.length; k++) {
302	      const s = sorted[k];
303	      const e = sorted[k + 1];
304	      let anyAnomaly = false;
305	      let anyUnknown = false;
306	      let slice = 0n;
307	      const sliceGaps: GapDetail[] = [];
308	      for (const m of p.members) {
309	        const res = deviceSlice(seriesByDevice.get(m) ?? [], s, e, maxInterval);
310	        if (res.kind === 'anomaly') anyAnomaly = true;
311	        else if (res.kind === 'unknown') {
312	          anyUnknown = true;
313	          if (res.gap) sliceGaps.push({ device: m, start: res.gap.start, end: res.gap.end });
314	        } else slice += res.consumption;
315	      }
316	      if (anyAnomaly) {
317	        anomaly += e - s;
318	      } else if (anyUnknown) {
319	        unknown += e - s;
320	        // 过长间隔未知只在最终未知时段内按实际时间计并集:同一子片段内
321	        // 任一成员有过长区间即计一次,不叠加成员秒数。
322	        if (sliceGaps.length > 0) {
323	          gapUnknown += e - s;
324	          mergeGaps(gaps, sliceGaps);
325	        }
326	      } else {
327	        valid += e - s;
328	        consumption += slice;
329	      }
330	    }
331	  }
332	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption, periods };
333	}
334	
335	/**
336	 * 配置分组成员版本。首次配置即建立分组;同组同一实际生效时刻、同成员集合
337	 * 重试成功且不新增,异成员集合报冲突。整次成功或不提交。返回进程退出码。
338	 */
339	export function cmdGroupConfigure(opts: { id: string; at: number; members: string[] }): number {
340	  const path = groupFilePath();
341	  let groups: Group[];
342	  try {
343	    groups = loadGroups(path);
344	  } catch (e) {
345	    if (e instanceof StoreError) {
346	      err(e.message);
347	      return 1;
348	    }
349	    throw e;
350	  }
351	
352	  // 规范形:同设备重复列出只算一次,成员顺序不影响等价性。
353	  const members = [...new Set(opts.members)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
354	
355	  let known: Set<string>;
356	  try {
357	    known = new Set(loadStore(dataFilePath()).map((r) => r.device));
358	  } catch (e) {
359	    if (e instanceof StoreError) {
360	      err(e.message);
361	      return 1;
362	    }
363	    throw e;
364	  }
365	  for (const m of members) {
366	    if (!known.has(m)) {
367	      err(`unknown device '${m}': no stored readings; import readings before configuring a group`);
368	      return 1;
369	    }
370	  }
371	
372	  const existing = groups.find((g) => g.id === opts.id);
373	  if (existing) {
374	    const v = existing.versions.find((ver) => ver.at === opts.at);
375	    if (v) {
376	      const same =
377	        v.members.length === members.length && v.members.every((m, i) => m === members[i]);
378	      if (same) {
379	        console.log(
380	          `group '${opts.id}' already has an identical member version at ${formatIsoUtc(opts.at)}; unchanged`,
381	        );
382	        return 0;
383	      }
384	      err(
385	        `group '${opts.id}' already has a different member version at ${formatIsoUtc(opts.at)} ` +
386	          `(stored members=${v.members.join(',')}, got members=${members.join(',')}); conflict`,
387	      );
388	      return 1;
389	    }
390	    existing.versions.push({ at: opts.at, members });
391	    existing.versions.sort((a, b) => a.at - b.at);
392	  } else {
393	    groups.push({ id: opts.id, versions: [{ at: opts.at, members }] });
394	  }
395	
396	  try {
397	    saveGroups(path, groups);
398	  } catch (e) {
399	    if (e instanceof StoreError) {
400	      err(e.message);
401	      return 1;
402	    }
403	    throw e;
404	  }
405	  console.log(
406	    `group '${opts.id}' configured: members=${members.join(',')} effective ${formatIsoUtc(opts.at)}`,
407	  );
408	  return 0;
409	}
410	
411	/** 查看分组成员版本历史,按生效时刻排序。只读。返回进程退出码。 */
412	export function cmdGroupHistory(opts: { id: string }): number {
413	  let groups: Group[];
414	  try {
415	    groups = loadGroups(groupFilePath());
416	  } catch (e) {
417	    if (e instanceof StoreError) {
418	      err(e.message);
419	      return 1;
420	    }
421	    throw e;
422	  }
423	  const group = groups.find((g) => g.id === opts.id);
424	  if (!group) {
425	    err(`unknown group '${opts.id}'`);
426	    return 1;
427	  }
428	  console.log(`group: ${group.id}`);
429	  for (const v of group.versions) {
430	    console.log(`  ${formatIsoUtc(v.at)}  members=${v.members.join(',')}`);
431	  }
432	  return 0;
433	}
434	
435	/**
436	 * 分组能耗日报:按当地自然日切分(默认 UTC,--tz 指定 IANA 时区),按当时
437	 * 生效成员计算。只读,不写入数据。返回进程退出码。
438	 */
439	export function cmdGroupDaily(opts: {
440	  id: string;
441	  from: number;
442	  to: number;
443	  tz?: string;
444	  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
445	  maxInterval?: number;
446	}): number {
447	  const tzName = opts.tz ?? 'UTC';
448	  const tz = loadTimezone(tzName);
449	  if (!tz) {
450	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
451	    return 2;
452	  }
453	
454	  let groups: Group[];
455	  try {
456	    groups = loadGroups(groupFilePath());
457	  } catch (e) {
458	    if (e instanceof StoreError) {
459	      err(e.message);
460	      return 1;
461	    }
462	    throw e;
463	  }
464	  const group = groups.find((g) => g.id === opts.id);
465	  if (!group) {
466	    err(`unknown group '${opts.id}'`);
467	    return 1;
468	  }
469	
470	  let seriesByDevice: Map<string, Reading[]>;
471	  try {
472	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
473	  } catch (e) {
474	    if (e instanceof StoreError) {
475	      err(e.message);
476	      return 1;
477	    }
478	    throw e;
479	  }
480	
481	  const days = localDays(tz, opts.from, opts.to);
482	
483	  console.log(`group: ${group.id}`);
484	  console.log(`timezone: ${tzName}`);
485	  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);
486	  let total = 0n;
487	  let computedDays = 0;
488	  let incomplete = false;
489	  for (const day of days) {
490	    let valid = 0;
491	    let anomaly = 0;
492	    let unknown = 0;
493	    let gapUnknown = 0;
494	    const gaps: GapDetail[] = [];
495	    let consumption = 0n;
496	    const periods: GroupPeriod[] = [];
497	    for (const p of day.periods) {
498	      const stats = computeGroupSegment(group.versions, seriesByDevice, p.start, p.end, opts.maxInterval);
499	      valid += stats.valid;
500	      anomaly += stats.anomaly;
501	      unknown += stats.unknown;
502	      gapUnknown += stats.gapUnknown;
503	      mergeGaps(gaps, stats.gaps);
504	      consumption += stats.consumption;
505	      periods.push(...stats.periods);
506	    }
507	    const dayIncomplete = anomaly > 0 || unknown > 0;
508	    if (dayIncomplete) incomplete = true;
509	
510	    let consumptionText: string;
511	    if (valid > 0) {
512	      consumptionText = `consumption=${formatKwh(consumption)} kWh (estimate)`;
513	      total += consumption;
514	      computedDays++;
515	    } else {
516	      consumptionText = 'consumption=n/a (no valid coverage)';
517	    }
518	    let line =
519	      `  ${day.label}  ${consumptionText}` +
520	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
521	    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
522	    if (dayIncomplete) line += '  INCOMPLETE';
523	    console.log(line);
524	    for (const p of day.periods) {
525	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
526	    }
527	    for (const p of periods) {
528	      const members = p.members === null ? '(no version in effect)' : p.members.join(',');
529	      console.log(
530	        `    members=${members}  period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`,
531	      );
532	    }
533	    for (const g of gaps) {
534	      console.log(formatGapLine(g));
535	    }
536	  }
537	
538	  const totalText =
539	    computedDays > 0
540	      ? `total consumption=${formatKwh(total)} kWh (estimate)`
541	      : 'total consumption=n/a (no valid coverage)';
542	  const status = incomplete
543	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
544	    : 'status=complete';
545	  console.log(
546	    `  summary: group=${group.id}  computed=${computedDays}/${days.length} day(s)  ${totalText}  ${status}`,
547	  );
548	  return 0;
549	}
