    // 当地日期标签按 UTC 解释即该日墙钟午夜的"墙钟 epoch",墙钟片段以此为基准。
    const midnight = parseUtcDate(day.label) as number;
    for (const p of day.periods) {
      const offset = tzOffsetAt(fmt, p.start);
      const relStart = p.start + offset - midnight;
      const relEnd = p.end + offset - midnight;
      let cursor = p.start;
      for (const [s, e] of segs) {
        const lo = Math.max(s, relStart);
        const hi = Math.min(e, relEnd);
        if (lo >= hi) continue;
        push(nonRunning, cursor, p.start + (lo - relStart));
        push(running, p.start + (lo - relStart), p.start + (hi - relStart));
        cursor = p.start + (hi - relStart);
      }
      push(nonRunning, cursor, p.end);
    }
  }
  return { running, nonRunning };
}

