// 命名时区分日:用运行环境自带的 Intl(ECMA-402)解析 IANA 时区,
// 按当地墙钟把查询范围切成自然日。不按固定 86400 秒或全年固定偏移
// 推算日界线:夏令时前拨跳过的当天更短(跳过的小时不存在,不补为未知),
// 回拨当天更长(重复小时按各自实际时刻完整计入);同一当地日期在不连续
// 时段出现时合并统计、时段分别保留;整日被跳过的当地日期没有实际时段,
// 不生成虚构日报。

import { formatIsoUtc, parseUtcDate } from './time.ts';

export interface LocalDayPeriod {
  /** 时段起点(含),epoch 秒。 */
  start: number;
  /** 时段终点(不含),epoch 秒。 */
  end: number;
}

export interface LocalDay {
  /** 当地日期标签,YYYY-MM-DD。 */
  label: string;
  /** 该当地日期在查询范围内的实际 UTC 时段,按时间升序、互不重叠。 */
  periods: LocalDayPeriod[];
}

export interface WallClock {
  /** 日期比较键,y*10000+m*100+d。 */
  key: number;
  /** 日期标签,YYYY-MM-DD。 */
  label: string;
  /** 墙钟分量按 UTC 解释的 epoch 秒(用于偏移与午夜推算)。 */
  naive: number;
  /** 下一个当地午夜的墙钟,按 UTC 解释的 epoch 秒。 */
  nextMidnight: number;
}

/** 时刻 t 的当地墙钟(日期标签与按 UTC 解释的墙钟 epoch 秒)。 */
export function wallClockAt(fmt: Intl.DateTimeFormat, t: number): WallClock {
  return wallClock(fmt, t);
}

/** 校验 IANA 时区名并构造墙钟格式化器;运行环境不支持时返回 null。 */
export function loadTimezone(name: string): Intl.DateTimeFormat | null {
  if (name === '') return null;
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: name,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    });
    fmt.format(0);
    return fmt;
  } catch {
    return null;
  }
}

/**
 * 把时区名解析为运行环境解析后的规范 IANA 名称(如 US/Eastern 解析为
 * America/New_York);运行环境不支持时返回 null。同一实际时区的不同写法
 * 解析为同一规范名,规则时区按规范名存储与比较。
 */
export function canonicalTimezone(name: string): string | null {
  const fmt = loadTimezone(name);
  if (fmt === null) return null;
  const resolved = fmt.resolvedOptions().timeZone;
  return typeof resolved === 'string' && resolved !== '' ? resolved : null;
}

/** 年月日时分秒按 UTC 解释的 epoch 秒(setUTCFullYear 以支持 0-99 年)。 */
function naiveEpoch(y: number, mo: number, d: number, h: number, mi: number, s: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(y, mo - 1, d);
  dt.setUTCHours(h, mi, s, 0);
  return dt.getTime() / 1000;
}

/** 时刻 t 在时区 fmt 下的墙钟。 */
function wallClock(fmt: Intl.DateTimeFormat, t: number): WallClock {
  let y = 0;
  let mo = 0;
  let d = 0;
  let h = 0;
  let mi = 0;
  let s = 0;
  for (const p of fmt.formatToParts(t * 1000)) {
    switch (p.type) {
      case 'year':
        y = Number(p.value);
        break;
      case 'month':
        mo = Number(p.value);
        break;
      case 'day':
        d = Number(p.value);
        break;
      case 'hour':
        h = Number(p.value);
        break;
      case 'minute':
        mi = Number(p.value);
        break;
      case 'second':
        s = Number(p.value);
        break;
    }
  }
  const pad = (n: number): string => String(n).padStart(2, '0');
  return {
    key: y * 10000 + mo * 100 + d,
    label: `${String(y).padStart(4, '0')}-${pad(mo)}-${pad(d)}`,
    naive: naiveEpoch(y, mo, d, h, mi, s),
    nextMidnight: naiveEpoch(y, mo, d, 0, 0, 0) + 86400,
  };
}

/** 时区在时刻 t 的偏移(墙钟 - UTC),秒。 */
function offsetAt(fmt: Intl.DateTimeFormat, t: number): number {
  return wallClock(fmt, t).naive - t;
}

/**
 * 时区在时刻 t 的偏移(墙钟 - UTC),秒;供按当地墙钟分类的报表使用。
 * 调用方需保证所讨论的时段内偏移恒定(localDays 切出的时段满足)。
 */
export function tzOffsetAt(fmt: Intl.DateTimeFormat, t: number): number {
  return offsetAt(fmt, t);
}

/**
 * 在 (t, limit] 内找第一个偏移与 o0 不同的时刻;没有返回 Infinity。
 * 先按小时步进定位再秒级二分;IANA 时区的相邻偏移切换间隔远大于一小时,
 * 一小时内两次切换且净偏移不变的情形不存在。
 */
function nextTransition(fmt: Intl.DateTimeFormat, t: number, o0: number, limit: number): number {
  let lo = t;
  let u = t;
  while (u < limit) {
    u = Math.min(u + 3600, limit);
    if (offsetAt(fmt, u) !== o0) {
      let hi = u;
      while (hi - lo > 1) {
        const mid = Math.floor((lo + hi) / 2);
        if (offsetAt(fmt, mid) !== o0) hi = mid;
        else lo = mid;
      }
      return hi;
    }
    lo = u;
  }
  return Infinity;
}

/**
 * 把 [from, to) 按当地自然日切分。返回按首次出现排序(即日期升序)的
 * 当地日期,每个日期带实际统计的 UTC 时段;同一日期的不连续时段合并到
 * 同一日期下分别列出,相邻时段并为一个区间。没有实际时段的当地日期
 * (如整体被跳过的日期)不出现。
 */
export function localDays(fmt: Intl.DateTimeFormat, from: number, to: number): LocalDay[] {
  const days: LocalDay[] = [];
  const byKey = new Map<number, LocalDay>();
  let cursor = from;
  while (cursor < to) {
    const w = wallClock(fmt, cursor);
    const o0 = w.naive - cursor;
    // 偏移不变时下一次日期变化的 UTC 时刻;wall(cursor) < nextMidnight,
    // 故 uStar > cursor 恒成立。
    const uStar = w.nextMidnight - o0;
    // 偏移切换可能先于午夜到达(如午夜前后切换夏令时),此时日期是否变化
    // 由下一轮以新偏移重新计算;段内偏移恒定,日期不会中途改变。
    const trans = nextTransition(fmt, cursor, o0, Math.min(uStar, to));
    const end = Math.min(uStar, trans, to);
    let day = byKey.get(w.key);
    if (!day) {
      day = { label: w.label, periods: [] };
      byKey.set(w.key, day);
      days.push(day);
    }
    const last = day.periods[day.periods.length - 1];
    if (last && last.end === cursor) last.end = end;
    else day.periods.push({ start: cursor, end });
    cursor = end;
  }
  return days;
}

export interface LocalDateEntry {
  /** 当地日期标签,YYYY-MM-DD,按当地日期升序。 */
  label: string;
  /** 归属该日期的全部实际 UTC 时段;null 表示整日被跳过(无实际时段)。 */
  day: LocalDay | null;
}

/**
 * 把连续日历日期范围 [fromLabel, toLabel)(YYYY-MM-DD,起日含、止日不含)映射为
 * 各当地日期在 fmt 时区下的实际 UTC 时段。每个日期统计归属该日期的全部实际
 * 时段,不把当地午夜简单套用固定偏移:夏令时短日的实际时段更短,回拨日更长,
 * 日期回退产生的不连续时段合并在同一日期下;整日被跳过的日期 day 为 null,
 * 由调用方标明跳过。日历日期本身按格里历逐日递增,与时区无关。
 */
export function localDateRange(
  fmt: Intl.DateTimeFormat,
  fromLabel: string,
  toLabel: string,
): LocalDateEntry[] {
  const fromUtc = parseUtcDate(fromLabel) as number;
  const toUtc = parseUtcDate(toLabel) as number;
  // 任一日期的当地午夜与 UTC 午夜之差不超过该时区的最大偏移(远小于两天),
  // 向两侧放宽后再切分,保证首尾日期的实际时段完整落入切分范围。
  const margin = 2 * 86400;
  const days = localDays(fmt, fromUtc - margin, toUtc + margin);
  const byLabel = new Map<string, LocalDay>();
  for (const d of days) byLabel.set(d.label, d);
  const out: LocalDateEntry[] = [];
  for (let t = fromUtc; t < toUtc; t += 86400) {
    const label = formatIsoUtc(t).slice(0, 10);
    out.push({ label, day: byLabel.get(label) ?? null });
  }
  return out;
}

// 每周运行时间表:本地文本文件,把查询范围划分为运行与非运行两类时段。
//
// 文件格式:零个或多个窗口,每行一个
//   <星期> <开始 HH:mm> <结束 HH:mm>
// - 星期:mon..sun 或 monday..sunday,不区分大小写;
// - 开始限 00:00..23:59,结束另可 24:00;起止相同拒绝;
// - 结束早于开始即跨至下一日,尾段(次日 [00:00, 结束))沿用开始日规则,
//   周日可跨至周一;
// - 窗口起点含、终点不含,重叠或重复取并集;
// - 空行与 # 开头的行忽略;空表(零个窗口)表示全部非运行。
//
// 分类按实际时刻在指定时区的当地日期与墙钟,每秒只属一类:夏令时前拨
// 跳过的墙钟不存在,不虚构覆盖;回拨重复的墙钟各段各自按当时墙钟分类;
// 不按固定偏移或固定日长推算。

import { parseUtcDate } from './time.ts';
import { localDays, tzOffsetAt } from './tz.ts';

export interface ScheduleWindow {
  /** 开始星期,0=周日 .. 6=周六。 */
  startDay: number;
  /** 开始时刻,当地午夜起分钟数(0..1439)。 */
  startMin: number;
  /** 结束时刻,当地午夜起分钟数(0..1440;1440 即 24:00)。 */
  endMin: number;
}

export interface ClassPeriod {
  /** 时段起点(含),epoch 秒。 */
  start: number;
  /** 时段终点(不含),epoch 秒。 */
  end: number;
}

export interface ClassifiedPeriods {
  /** 运行时段,按时间升序、互不重叠(相邻同类时段已合并)。 */
  running: ClassPeriod[];
  /** 非运行时段,按时间升序、互不重叠;与运行时段合计恰好覆盖查询范围。 */
  nonRunning: ClassPeriod[];
}

const WEEKDAYS: Record<string, number> = {
  sun: 0,
  sunday: 0,
  mon: 1,
  monday: 1,
  tue: 2,
  tuesday: 2,
  wed: 3,
  wednesday: 3,
  thu: 4,
  thursday: 4,
  fri: 5,
  friday: 5,
  sat: 6,
  saturday: 6,
};

const CLOCK_RE = /^(\d{2}):(\d{2})$/;

/** 解析 HH:mm 为当地午夜起分钟数;endOfDay 时另允许 24:00(=1440)。失败返回 null。 */
function parseClock(raw: string, endOfDay: boolean): number | null {
  const m = CLOCK_RE.exec(raw);
  if (!m) return null;
  const hh = Number(m[1]);
  const mm = Number(m[2]);
  if (mm > 59) return null;
  if (hh === 24) return endOfDay && mm === 0 ? 1440 : null;
  if (hh > 23) return null;
  return hh * 60 + mm;
}

/**
 * 解析每周运行时间表文本。成功返回窗口数组(可为空,空表全部非运行);
 * 任一窗口非法返回错误消息字符串(含行号),由调用方按参数错误处理。
 */
export function parseSchedule(text: string): ScheduleWindow[] | string {
  const windows: ScheduleWindow[] = [];
  const lines = text.split(/\r\n|\r|\n/);
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const line = lines[i].trim();
    if (line === '' || line.startsWith('#')) continue;
    const fields = line.split(/\s+/);
    if (fields.length !== 3) {
      return `第 ${lineNo} 行:需要 '<星期> <开始 HH:mm> <结束 HH:mm>' 三个字段`;
    }
    const day = WEEKDAYS[fields[0].toLowerCase()];
    if (day === undefined) {
      return `第 ${lineNo} 行:未知星期 '${fields[0]}'(需 mon..sun 或 monday..sunday,不区分大小写)`;
    }
    const startMin = parseClock(fields[1], false);
    if (startMin === null) {
      return `第 ${lineNo} 行:开始时刻无效 '${fields[1]}'(需 HH:mm,00:00..23:59)`;
    }
    const endMin = parseClock(fields[2], true);
    if (endMin === null) {
      return `第 ${lineNo} 行:结束时刻无效 '${fields[2]}'(需 HH:mm,00:00..23:59 或 24:00)`;
    }
    if (startMin === endMin) {
      return `第 ${lineNo} 行:窗口起止时刻相同('${fields[1]}'),拒绝`;
    }
    windows.push({ startDay: day, startMin, endMin });
  }
  return windows;
}

/** 当地日期标签(YYYY-MM-DD)的星期,0=周日 .. 6=周六(格里历,与时区无关)。 */
function weekdayOfLabel(label: string): number {
  const [y, m, d] = label.split('-').map(Number);
  const dt = new Date(0);
  dt.setUTCFullYear(y, m - 1, d);
  return dt.getUTCDay();
}

/**
 * 某星期几的运行墙钟片段(当地午夜起秒数,已排序并取并集)。
 * 跨日窗口在开始日贡献 [开始, 24:00),在次日贡献尾段 [00:00, 结束)。
 */
function runningSegments(windows: ScheduleWindow[], day: number): Array<[number, number]> {
  const segs: Array<[number, number]> = [];
  for (const w of windows) {
    const cross = w.endMin < w.startMin;
    if (w.startDay === day) segs.push([w.startMin * 60, (cross ? 1440 : w.endMin) * 60]);
    if (cross && (w.startDay + 1) % 7 === day) segs.push([0, w.endMin * 60]);
  }
  segs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged: Array<[number, number]> = [];
  for (const [s, e] of segs) {
    const last = merged[merged.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else merged.push([s, e]);
  }
  return merged;
}

/**
 * 把 [from, to) 按时间表分为运行与非运行两类实际 UTC 时段。
 * 每个当地日期的实际 UTC 时段(由 localDays 给出,段内偏移恒定)按墙钟
 * 与该日期的运行片段求交;夏令时跳过的墙钟不产生时段,回拨重复的墙钟
 * 两段各自分类。两类合计恰好覆盖 [from, to),每秒只属一类。
 */
export function classifySchedule(
  fmt: Intl.DateTimeFormat,
  windows: ScheduleWindow[],
  from: number,
  to: number,
): ClassifiedPeriods {
  const running: ClassPeriod[] = [];
  const nonRunning: ClassPeriod[] = [];
  const push = (into: ClassPeriod[], start: number, end: number): void => {
    if (start >= end) return;
    const last = into[into.length - 1];
    if (last && last.end === start) last.end = end;
    else into.push({ start, end });
  };
  for (const day of localDays(fmt, from, to)) {
    const segs = runningSegments(windows, weekdayOfLabel(day.label));
    // 当地日期标签按 UTC 解释即该日墙钟午夜的"墙钟 epoch",墙钟片段以此为基准。
    const midnight = parseUtcDate(day.label) as number;
    for (const p of day.periods) {
      const offset = tzOffsetAt(fmt, p.start);
      const relStart = p.start + offset - midnight;
      const relEnd = p.end + offset - midnight;
      let cursor = p.start;
      for (const [s, e] of segs) {
        const lo = Math.max(s, relStart);
        const hi = Math.min(e, relEnd);
        if (lo >= hi) continue;
        push(nonRunning, cursor, p.start + (lo - relStart));
        push(running, p.start + (lo - relStart), p.start + (hi - relStart));
        cursor = p.start + (hi - relStart);
      }
      push(nonRunning, cursor, p.end);
    }
  }
  return { running, nonRunning };
}

